    let artifact = catalog.submit_artifact(
        &journal,
        &workflow,
        RuntimePolicy::Strict,
        &[contract],
        &[pack],
    )?;
    assert_eq!(artifact.accepted_at_seq.get(), 1);
    Ok(())
}

