    journal
        .artifact_acceptance
        .insert(b"last_issued", &[1, 2, 3, 4, 5, 6, 7])?;

    let result = catalog.submit_artifact(
        &journal,
        &workflow,
        RuntimePolicy::Relaxed,
        &[contract],
        &[pack],
    );
    match &result {
        Err(ExecutorError::Artifact(JournalError::MalformedKeyspaceRow {
            prefix,
            expected_len,
            actual_len,
